import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Trash2 } from 'lucide-react';
import FileUpload from './components/FileUpload';
import ProductUpload from './components/ProductUpload';
import KPIHeader from './components/KPIHeader';
import ConsolidationAlerts from './components/ConsolidationAlerts';
import OrdersTable from './components/OrdersTable';
import AnalyticsChart from './components/AnalyticsChart';
import './App.css';

function App() {
  const [orders, setOrders] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchLatestOrders = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:5000/api/orders/latest');
      setOrders(response.data.orders || []);
      setAlerts(response.data.alerts || []);
    } catch (error) {
      console.error('Error fetching orders:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLatestOrders();
  }, []);

  const handleUploadSuccess = (data) => {
    setOrders(data.orders);
    setAlerts(data.alerts);
  };

  const handleUpdateActualTrucks = async (id, actualTrucks) => {
    try {
      await axios.patch(`http://localhost:5000/api/orders/${id}/actual`, { actualTrucks });
      fetchLatestOrders();
    } catch (error) {
      console.error('Error updating actual trucks:', error);
    }
  };

  const handleDeleteLatest = async () => {
    if (window.confirm('Are you sure you want to delete the latest uploaded data?')) {
      try {
        setLoading(true);
        await axios.delete('http://localhost:5000/api/orders/latest');
        setOrders([]);
        setAlerts([]);
      } catch (error) {
        console.error('Error deleting latest orders:', error);
        alert('Error deleting data');
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 p-6 font-sans">
      <header className="mb-8 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="flex-shrink-0">
            <img src="/Logo.png" alt="Logo" className="h-16 w-auto object-contain" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-slate-900">Fleet Control Dashboard</h1>
            <p className="text-slate-500 mt-1">Truck Capacity & Logistics Optimization System</p>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        <div className="lg:col-span-2">
          <KPIHeader orders={orders} />
        </div>
        <div className="flex flex-col">
          <FileUpload onUploadSuccess={handleUploadSuccess} />
          <ProductUpload />
        </div>
      </div>

      {alerts.length > 0 && <ConsolidationAlerts alerts={alerts} />}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        <div className="xl:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 p-6 overflow-hidden">
          <div className="flex items-center justify-between mb-6 border-b pb-4">
            <h2 className="text-xl font-bold text-slate-800">Branch Details & Recommended Trucks</h2>
            {orders.length > 0 && (
              <button 
                onClick={handleDeleteLatest}
                className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-600 hover:bg-red-100 rounded-lg transition-colors font-medium text-sm border border-red-200"
              >
                <Trash2 className="w-4 h-4" />
                Clear Today's Data
              </button>
            )}
          </div>
          {loading ? (
            <div className="flex justify-center p-12"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div></div>
          ) : (
            <OrdersTable orders={orders} onUpdateActual={handleUpdateActualTrucks} />
          )}
        </div>
        <div className="xl:col-span-1">
          <AnalyticsChart orders={orders} />
        </div>
      </div>
    </div>
  );
}

export default App;
